-- PostgreSQL: one atomic statement. Requires an existing users.id = 1.
-- Design: Equal-width magazine columns, plum identity, project-led left column, tinted skills panel.
-- All profile details, organizations, and accomplishments are fictional.
-- Each execution creates a new resume; IDs are generated by the database.
WITH
content AS (
    SELECT $resume_data$
[
{"label": "Identity", "type": "header", "columnPosition": 0, "showHeading": false, "styling": {"border": {"bottom": {"display": true, "width": "86%", "height": "1px", "style": "solid", "color": "#683F65"}}}, "layout": {"display": "grid", "grid": {"columns": 1}, "padding": {"top": "0rem", "bottom": "0rem"}}, "value": [{"type": "heading", "textAlign": "left", "children": [{"text": "IDENTITY", "bold": true, "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#683F65"}]}], "subsections": [{"label": "Jane Doe", "fields": [{"label": "Name", "value": [{"type": "paragraph", "label": "Name", "children": [{"text": "JANE DOE", "fontSizeOffset": 20, "lineHeightOffset": 0, "bold": true, "color": "#683F65"}]}], "layout": {}}, {"label": "Title", "value": [{"type": "paragraph", "label": "Title", "children": [{"text": "BRAND DESIGNER", "fontSizeOffset": 1, "lineHeightOffset": 0, "bold": true, "color": "#683F65"}]}], "layout": {}}, {"label": "Tagline", "value": [{"type": "paragraph", "label": "Tagline", "children": [{"text": "Identity. Story. Expression.", "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#736571"}]}], "layout": {}}]}]},
{"label": "About", "type": "summary", "columnPosition": 0, "showHeading": true, "styling": {}, "layout": {"display": "grid", "grid": {"columns": 1}, "padding": {"top": "0rem", "bottom": "0rem"}}, "value": [{"type": "heading", "textAlign": "left", "children": [{"text": "ABOUT", "bold": true, "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#683F65"}]}], "subsections": [{"label": "About", "fields": [{"label": "Summary", "value": [{"type": "paragraph", "label": "Summary", "children": [{"text": "Brand designer with 6 years of experience creating expressive identities for growing businesses. Combines strategic thinking with careful typography and a practical approach to delivery.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}], "layout": {}}]}]},
{"label": "Selected Projects", "type": "projects", "columnPosition": 0, "showHeading": true, "styling": {}, "layout": {"display": "grid", "grid": {"columns": 1}, "padding": {"top": "0rem", "bottom": "0rem"}}, "value": [{"type": "heading", "textAlign": "left", "children": [{"text": "SELECTED PROJECTS", "bold": true, "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#683F65"}]}], "subsections": [{"label": "Meadow Market", "fields": [{"label": "Project Title", "value": [{"type": "paragraph", "label": "Project Title", "children": [{"text": "Meadow Market", "fontSizeOffset": 1, "lineHeightOffset": 0, "bold": true}]}], "layout": {}}, {"label": "Category", "value": [{"type": "paragraph", "label": "Category", "children": [{"text": "Retail identity / 2025", "fontSizeOffset": -0.5, "lineHeightOffset": 0, "color": "#683F65"}]}], "layout": {}}, {"label": "Description", "value": [{"type": "paragraph", "label": "Description", "children": [{"text": "Created a friendly visual identity, packaging system, and launch toolkit for a neighborhood food brand. Delivered 35 reusable assets across print and digital channels.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}], "layout": {}}]}, {"label": "Lumen Festival", "fields": [{"label": "Project Title", "value": [{"type": "paragraph", "label": "Project Title", "children": [{"text": "Lumen Festival", "fontSizeOffset": 1, "lineHeightOffset": 0, "bold": true}]}], "layout": {}}, {"label": "Category", "value": [{"type": "paragraph", "label": "Category", "children": [{"text": "Culture campaign / 2024", "fontSizeOffset": -0.5, "lineHeightOffset": 0, "color": "#683F65"}]}], "layout": {}}, {"label": "Description", "value": [{"type": "paragraph", "label": "Description", "children": [{"text": "Designed a modular campaign for a 3-day arts festival. Unified signage, event programs, and social templates for 20 participating artists.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}], "layout": {}}]}]},
{"label": "Contact", "type": "contact", "columnPosition": 0, "showHeading": true, "styling": {}, "layout": {"display": "grid", "grid": {"columns": 1}, "padding": {"top": "0rem", "bottom": "0rem"}}, "value": [{"type": "heading", "textAlign": "left", "children": [{"text": "CONTACT", "bold": true, "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#683F65"}]}], "subsections": [{"label": "Contact", "fields": [{"label": "Email", "value": [{"type": "paragraph", "label": "Email", "children": [{"text": "jane.doe@example.com", "fontSizeOffset": 0, "lineHeightOffset": 0}]}], "layout": {}}, {"label": "Phone", "value": [{"type": "paragraph", "label": "Phone", "children": [{"text": "(312) 555-0182", "fontSizeOffset": 0, "lineHeightOffset": 0}]}], "layout": {}}, {"label": "Location", "value": [{"type": "paragraph", "label": "Location", "children": [{"text": "Chicago, IL", "fontSizeOffset": 0, "lineHeightOffset": 0}]}], "layout": {}}, {"label": "Portfolio", "value": [{"type": "paragraph", "label": "Portfolio", "children": [{"text": "janedoe.example.com", "fontSizeOffset": 0, "lineHeightOffset": 0}]}], "layout": {}}]}]},
{"label": "Experience", "type": "workHistory", "columnPosition": 1, "showHeading": true, "styling": {}, "layout": {"display": "grid", "grid": {"columns": 1}, "padding": {"top": "0rem", "bottom": "0rem"}}, "value": [{"type": "heading", "textAlign": "left", "children": [{"text": "EXPERIENCE", "bold": true, "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#683F65"}]}], "subsections": [{"label": "Velvet Elm Studio", "fields": [{"label": "Job Title", "value": [{"type": "paragraph", "label": "Job Title", "children": [{"text": "Senior Brand Designer", "fontSizeOffset": 1, "lineHeightOffset": 0, "bold": true}]}], "layout": {}}, {"label": "Company", "value": [{"type": "paragraph", "label": "Company", "children": [{"text": "Velvet Elm Studio | 2023 - Present", "fontSizeOffset": -0.5, "lineHeightOffset": 0, "color": "#606873"}]}], "layout": {}}, {"label": "Description", "value": [{"type": "unordered-list", "children": [{"type": "list-item", "children": [{"text": "Led 9 identity projects from discovery through rollout.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}, {"type": "list-item", "children": [{"text": "Built reusable presentation and production templates, reducing revision cycles by 25%.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}], "layout": {}}]}, {"label": "Mosaic Bird Creative", "fields": [{"label": "Job Title", "value": [{"type": "paragraph", "label": "Job Title", "children": [{"text": "Visual Designer", "fontSizeOffset": 1, "lineHeightOffset": 0, "bold": true}]}], "layout": {}}, {"label": "Company", "value": [{"type": "paragraph", "label": "Company", "children": [{"text": "Mosaic Bird Creative | 2020 - 2023", "fontSizeOffset": -0.5, "lineHeightOffset": 0, "color": "#606873"}]}], "layout": {}}, {"label": "Description", "value": [{"type": "unordered-list", "children": [{"type": "list-item", "children": [{"text": "Designed web, packaging, and campaign assets for 12 client accounts.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}, {"type": "list-item", "children": [{"text": "Partnered with writers and developers to deliver consistent brand experiences.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}], "layout": {}}]}]},
{"label": "Design Practice", "type": "skills", "columnPosition": 1, "showHeading": true, "styling": {"backgroundColor": "#F5EEF4"}, "layout": {"display": "grid", "grid": {"columns": 1}, "padding": {"top": "0rem", "bottom": "0rem"}}, "value": [{"type": "heading", "textAlign": "left", "children": [{"text": "DESIGN PRACTICE", "bold": true, "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#683F65"}]}], "subsections": [{"label": "Practice", "fields": [{"label": "Strategy", "value": [{"type": "paragraph", "label": "Strategy", "children": [{"text": "Brand strategy / Art direction", "fontSizeOffset": 0, "lineHeightOffset": 0}]}], "layout": {}}, {"label": "Craft", "value": [{"type": "paragraph", "label": "Craft", "children": [{"text": "Typography / Layout / Packaging", "fontSizeOffset": 0, "lineHeightOffset": 0}]}], "layout": {}}, {"label": "Tools", "value": [{"type": "paragraph", "label": "Tools", "children": [{"text": "Figma / Illustrator / InDesign", "fontSizeOffset": 0, "lineHeightOffset": 0}]}], "layout": {}}]}]},
{"label": "Education", "type": "education", "columnPosition": 1, "showHeading": true, "styling": {}, "layout": {"display": "grid", "grid": {"columns": 1}, "padding": {"top": "0rem", "bottom": "0rem"}}, "value": [{"type": "heading", "textAlign": "left", "children": [{"text": "EDUCATION", "bold": true, "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#683F65"}]}], "subsections": [{"label": "College", "fields": [{"label": "Degree", "value": [{"type": "paragraph", "label": "Degree", "children": [{"text": "B.F.A. Graphic Design", "fontSizeOffset": 1, "lineHeightOffset": 0, "bold": true}]}], "layout": {}}, {"label": "School", "value": [{"type": "paragraph", "label": "School", "children": [{"text": "Westmere College", "fontSizeOffset": 0, "lineHeightOffset": 0}]}], "layout": {}}, {"label": "Dates", "value": [{"type": "paragraph", "label": "Dates", "children": [{"text": "2016 - 2020", "fontSizeOffset": -0.5, "lineHeightOffset": 0}]}], "layout": {}}]}]}
]
$resume_data$::jsonb AS sections
),
new_resume AS (
    INSERT INTO resumes (user_id, title, styling, layout, created_at, updated_at)
    VALUES (
        1,
        'Jane Doe - Plum Studio',
        '{"display": "flex", "fontFamily": "Arial, Helvetica, sans-serif", "fontSize": "13.5px", "lineHeight": 1.3, "color": "#30343B", "backgroundColor": "#FFFFFF"}'::json,
        '{"padding": {"top": "1.8rem", "right": "1.8rem", "bottom": "1.8rem", "left": "1.8rem"}, "gap": {"horizontal": "0.3rem", "vertical": "0.4rem", "subsection": "0.6rem", "field": "0.14rem"}}'::json,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    )
    RETURNING id, title
),
new_columns AS (
    INSERT INTO columns (resume_id, position, styling, layout, created_at, updated_at)
    SELECT r.id, c.position, '{}'::json, c.layout,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    FROM new_resume r
    CROSS JOIN (VALUES
        (0, '{"width": {"auto": false, "value": "50%"}, "padding": {"top": "0rem", "bottom": "0rem", "left": "0.8rem", "right": "0.8rem"}}'::json),
        (1, '{"width": {"auto": false, "value": "50%"}, "padding": {"top": "0rem", "bottom": "0rem", "left": "0.8rem", "right": "0.8rem"}}'::json)
    ) AS c(position, layout)
    RETURNING id, position
),
section_data AS (
    SELECT (s.ordinality - 1)::integer AS position, s.item
    FROM content
    CROSS JOIN LATERAL jsonb_array_elements(content.sections)
        WITH ORDINALITY AS s(item, ordinality)
),
new_sections AS (
    INSERT INTO sections (
        column_id, label, type, value, show_heading, position,
        styling, layout, created_at, updated_at
    )
    SELECT c.id, s.item->>'label', s.item->>'type',
        (s.item->'value')::json,
        (s.item->>'showHeading')::boolean, s.position,
        (s.item->'styling')::json, (s.item->'layout')::json,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    FROM section_data s
    JOIN new_columns c ON c.position = (s.item->>'columnPosition')::integer
    RETURNING id, position
),
subsection_data AS (
    SELECT s.id AS section_id, (sub.ordinality - 1)::integer AS position, sub.item
    FROM new_sections s
    JOIN section_data d ON d.position = s.position
    CROSS JOIN LATERAL jsonb_array_elements(d.item->'subsections')
        WITH ORDINALITY AS sub(item, ordinality)
),
new_subsections AS (
    INSERT INTO subsections (
        section_id, label, type, position, styling, layout, created_at, updated_at
    )
    SELECT d.section_id, d.item->>'label', s.item->>'type', d.position,
        '{"fontSizeOffset":0,"lineHeightOffset":0}'::json, '{}'::json,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    FROM subsection_data d
    JOIN new_sections n ON n.id = d.section_id
    JOIN section_data s ON s.position = n.position
    RETURNING id, section_id, position
),
new_fields AS (
    INSERT INTO fields (
        subsection_id, label, value, position, styling, layout, created_at, updated_at
    )
    SELECT sub.id, f.item->>'label', (f.item->'value')::json,
        (f.ordinality - 1)::integer,
        '{"fontSizeOffset":0,"lineHeightOffset":0}'::json, COALESCE((f.item->'layout')::json, '{}'::json),
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    FROM new_subsections sub
    JOIN subsection_data d ON d.section_id = sub.section_id AND d.position = sub.position
    CROSS JOIN LATERAL jsonb_array_elements(d.item->'fields')
        WITH ORDINALITY AS f(item, ordinality)
    RETURNING id
)
SELECT id AS resume_id, title, (SELECT count(*) FROM new_fields) AS fields_created
FROM new_resume;
